//! Live data feed for static draft pages.
//!
//! A page's optional `source` block names a D-Bus plugin object; data is
//! fetched over the existing gRPC bridge on the same server via
//! `operation.v1.PluginService/CallMethod` — no per-service protos, no
//! extra endpoints (this is the same path `zcall` takes). The unwrapped
//! `result` payload becomes the bind root for the page, replacing the
//! static `data` sample once the plugin returns something non-empty.

use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;

use parking_lot::Mutex;
use serde_json::{json, Value};
use tokio::task::AbortHandle;

use crate::catalog::static_pages::PageSource;
use crate::grpc::{invoke_unary, ReflectionRegistry};

/// Latest live state for one page, polled by the UI each frame.
#[derive(Clone, Default)]
pub struct PageLive {
    /// Unwrapped `result` from the last successful call, if non-empty.
    pub value: Option<Value>,
    /// Human status line shown next to the draft badge.
    pub status: String,
}

struct Entry {
    /// Fingerprint of the source that spawned the task; a hot-reload edit
    /// that changes the source aborts and respawns.
    fingerprint: String,
    live: PageLive,
    abort: AbortHandle,
}

#[derive(Clone, Default)]
pub struct PageDataHub {
    inner: Arc<Mutex<HashMap<String, Entry>>>,
}

fn is_empty_result(v: &Value) -> bool {
    match v {
        Value::Null => true,
        Value::Array(a) => a.is_empty(),
        Value::Object(o) => o.is_empty(),
        Value::String(s) => s.is_empty(),
        _ => false,
    }
}

impl PageDataHub {
    pub fn new() -> Self { Self::default() }

    pub fn live(&self, slug: &str) -> Option<PageLive> {
        self.inner.lock().get(slug).map(|e| e.live.clone())
    }

    /// Make sure a poll task is running for this page's source. Called every
    /// frame for the visible route; cheap when already running.
    pub fn ensure(
        &self,
        slug: &str,
        source: &PageSource,
        reg: ReflectionRegistry,
        ctx: egui::Context,
    ) {
        let fingerprint = format!("{source:?}");
        {
            let map = self.inner.lock();
            if map.get(slug).is_some_and(|e| e.fingerprint == fingerprint) {
                return;
            }
        }

        let inner = self.inner.clone();
        let slug_owned = slug.to_string();
        let src = source.clone();
        let handle = tokio::spawn(async move {
            let request = json!({
                "plugin_id": src.plugin,
                "object_path": format!("/org/opdbus/v1/plugins/{}", src.plugin),
                "interface_name": "org.opdbus.v1.Plugin",
                "method_name": src.method,
                "arguments": src.args,
                "actor_id": "",
                "capability_id": "",
            });
            loop {
                if reg.pool().is_none() || reg.channel().is_none() {
                    set_status(&inner, &slug_owned, "waiting for gRPC reflection…");
                    tokio::time::sleep(Duration::from_secs(1)).await;
                    continue;
                }
                let outcome =
                    invoke_unary(&reg, "operation.v1.PluginService", "CallMethod", &request).await;
                {
                    let mut map = inner.lock();
                    if let Some(entry) = map.get_mut(&slug_owned) {
                        match outcome {
                            Ok(resp) => {
                                let ok = resp.get("success").and_then(Value::as_bool).unwrap_or(false);
                                let result = resp.get("result").cloned().unwrap_or(Value::Null);
                                if ok && !is_empty_result(&result) {
                                    entry.live.value = Some(result);
                                    entry.live.status =
                                        format!("LIVE — {}.{}", src.plugin, src.method);
                                } else if ok {
                                    entry.live.status = format!(
                                        "static sample — {}.{} returned empty",
                                        src.plugin, src.method
                                    );
                                } else {
                                    let err = resp
                                        .get("error")
                                        .map(|e| e.to_string())
                                        .unwrap_or_else(|| "unknown error".into());
                                    entry.live.status =
                                        format!("static sample — plugin error: {err}");
                                }
                            }
                            Err(e) => {
                                entry.live.status = format!("static sample — gRPC: {e:#}");
                            }
                        }
                    }
                }
                ctx.request_repaint();
                tokio::time::sleep(Duration::from_secs(src.poll_secs.max(1))).await;
            }
        });

        let mut map = self.inner.lock();
        if let Some(old) = map.insert(slug.to_string(), Entry {
            fingerprint,
            live: PageLive { value: None, status: "connecting…".into() },
            abort: handle.abort_handle(),
        }) {
            old.abort.abort();
        }
    }
}

fn set_status(inner: &Arc<Mutex<HashMap<String, Entry>>>, slug: &str, status: &str) {
    if let Some(e) = inner.lock().get_mut(slug) {
        e.live.status = status.to_string();
    }
}

