use super::store::{ChatMessage, ChatStore};
use crate::theme::*;
use egui::{Align, Color32, FontId, Frame, Layout, Margin, RichText, Rounding, Sense, Stroke, Vec2};

/// Main entry point. Renders the full Antigravity chat page:
/// Left = transcript + composer
/// Right = catalog-backed structured inspector (json-render.dev)
pub fn render_chat(ui: &mut egui::Ui, store: &mut ChatStore, ctx: &egui::Context) {
    // Throttle repaint to ~60fps during streaming.
    if store.submitted && store.should_repaint() {
        ctx.request_repaint();
    }

    // === ANTIGRAVITY SPLIT LAYOUT ===
    ui.horizontal(|ui| {
        let total_w = ui.available_width();
        let left_w = (total_w * 0.58).max(420.0);
        let right_w = (total_w - left_w - 8.0).max(320.0);

        // LEFT PANE — Transcript + Composer
        ui.allocate_ui(egui::Vec2::new(left_w, ui.available_height()), |ui| {
            ui.vertical(|ui| {
                let available = ui.available_height();
                let composer_h = 88.0_f32;
                let transcript_h = (available - composer_h - 8.0).max(120.0);

                ui.allocate_ui(egui::Vec2::new(ui.available_width(), transcript_h), |ui| {
                    render_transcript(ui, store);
                });

                ui.add_space(4.0);

                ui.allocate_ui(egui::Vec2::new(ui.available_width(), composer_h), |ui| {
                    render_composer(ui, store);
                });
            });
        });

        ui.add_space(8.0);

        // RIGHT PANE — Antigravity Inspector (catalog-backed)
        ui.allocate_ui(egui::Vec2::new(right_w, ui.available_height()), |ui| {
            render_antigravity_inspector(ui, store);
        });
    });
}

/// Right-hand Antigravity inspector pane.
/// This is the ONLY allowed rendering path for structured payloads.
/// It resolves a catalog element via json-render.dev and calls interpret::render.
fn render_antigravity_inspector(ui: &mut egui::Ui, store: &ChatStore) {
    use crate::catalog::interpret;
    use crate::catalog::dsl::PinnedRef;

    Frame::none()
        .fill(SURFACE)
        .stroke(Stroke::new(1.0, BORDER))
        .rounding(Rounding::same(8.0))
        .inner_margin(Margin::symmetric(12.0, 10.0))
        .show(ui, |ui| {
            ui.vertical(|ui| {
                ui.label(
                    RichText::new("ANTIGRAVITY INSPECTOR")
                        .size(11.0)
                        .strong()
                        .color(MUTED),
                );
                ui.add_space(6.0);

                // Find the latest message that carries a catalog reference + value.
                // The gRPC stream (ChatFrame → UIMessagePart) is responsible for
                // emitting payloads with the shape:
                //   { "catalog_ref": { "id": "...", "version": 1 }, "value": { ... } }
                if let Some((pin, value)) = find_latest_structured_payload(&store.messages) {
                    // In a real app we would pass the live CatalogSnapshot here.
                    // For now we attempt render and show a clear error if the element
                    // is not yet in the catalog (this is the intended security behaviour).
                    let snapshot = crate::catalog::store::CatalogSnapshot::default(); // TODO: wire real snapshot from app state

                    if let Err(e) = interpret::render(ui, &snapshot, &pin, &value) {
                        ui.label(
                            RichText::new(format!("Render error: {}", e))
                                .size(11.0)
                                .color(DANGER),
                        );
                    }
                } else {
                    ui.label(
                        RichText::new("No structured payload yet.")
                            .size(11.0)
                            .color(MUTED)
                            .italics(),
                    );
                    ui.add_space(4.0);
                    ui.label(
                        RichText::new("When the assistant emits a catalog-backed structured part, it will render here via json-render.dev.")
                            .size(10.0)
                            .color(MUTED),
                    );
                }
            });
        });
}

/// Scans messages (newest first) for a payload containing a catalog reference.
/// Expected shape from gRPC:
///   { "catalog_ref": { "id": "...", "version": N }, "value": { ... } }
fn find_latest_structured_payload(messages: &[ChatMessage]) -> Option<(PinnedRef, serde_json::Value)> {
    for msg in messages.iter().rev() {
        if let Some(ref_obj) = msg.payload.get("catalog_ref") {
            if let (Some(id), Some(version)) = (
                ref_obj.get("id").and_then(|v| v.as_str()),
                ref_obj.get("version").and_then(|v| v.as_u64()),
            ) {
                let value = msg.payload.get("value").cloned().unwrap_or(serde_json::Value::Null);
                return Some((
                    PinnedRef {
                        id: id.to_string(),
                        version: version as u32,
                    },
                    value,
                ));
            }
        }
    }
    None
}

